-rw-r--r-- 1 root root 862 Aug 12 11:38 make_endpoint_windows.py
#!/usr/bin/env python3
import gzip
import sys


def open_text(path):
    with open(path, "rb") as handle:
        magic = handle.read(2)
    if magic == b"\x1f\x8b":
        return gzip.open(path, "rt")
    return open(path, "rt")


source, destination = sys.argv[1:3]
half_width = 20

with open_text(source) as src, open(destination, "w") as out:
    for index, line in enumerate(src, 1):
        if not line.strip() or line.startswith("#"):
            continue
        fields = line.rstrip("\n").split("\t")
        chrom, start_text, end_text = fields[:3]
        start = int(start_text)
        end = int(end_text)
        if start >= half_width:
            out.write(f"{chrom}\t{start-half_width}\t{start+half_width}\tS{index}\t0\t+\n")
        if end >= half_width:
            out.write(f"{chrom}\t{end-half_width}\t{end+half_width}\tE{index}\t0\t-\n")

